// LLM inbox for browser-side callers. GENERATED by llm-contact/build.sh on __DATE__ from
// ~/Documents/agent-coding/shared/llm-system-prompt-preamble.md, contact_eli_tool.json, note_to_eli_tool.json and
// llm_contact.py (`confirm-constants`, NOTE_RESULT_TEXT).
// Do not edit; edit the shared files and rebuild (the tests fail when this copy is stale).
//
// What it does (the browser cannot read files or run python3, so this is the in-page half of
// shared/llm_contact.py): systemPrompt() puts the shared preamble, word for word, in front of
// the app's own instructions; CONTACT_TOOL goes into every tools list; extract() finds a
// contact_eli call or an "@ELI:" line in a response. The cores then stop the task, write the
// message to the graph page `llm-inbox`, keep the full record in localStorage
// ("llm-inbox:records") and offer "copy LLM inbox records" so it can be forwarded with
//   python3 ~/Documents/agent-coding/shared/llm_contact.py report
//
// Notes (mirrors llm_contact.with_notes): NOTE_TOOL (note_to_eli) goes into the tools list next to
// CONTACT_TOOL. A call to it leaves Eli a message and the task carries on: withNotes() keeps a record
// marked `via: "note", halts: false` in the same store (`report` then files it as a note, exit 0), answers
// the call with NOTE_RESULT_TEXT and asks the model again. A note is never the answer and never stops anything.
//
// Confirm step (mirrors llm_contact.with_confirm): small models call contact_eli for routine
// remarks about the task, so before check() the cores run withConfirm(), which asks the model (only
// one listed in CONFIRM.confirm_models; any other model's call is sent unasked) one
// forced-choice question: send to Eli and stop, or it was a task remark and keep working. Sending
// is the default: any error or unclear answer hands back the original response, so a broken
// confirm step never loses a message. What a model chose not to send is kept apart from the
// records, in localStorage "llm-inbox:unconfirmed", so Eli can audit that nothing real is swallowed.
(function (root) {
  const PREAMBLE = __PREAMBLE__;
  const CONTACT_TOOL = __CONTACT_TOOL__;
  // the tool that does not stop the task, and the tool_result that answers a call to it (llm_contact.NOTE_TOOL, NOTE_RESULT_TEXT)
  const NOTE_TOOL = __NOTE_TOOL__;
  const NOTE_RESULT_TEXT = __NOTE_RESULT_TEXT__;
  const CONTACT_TOOLS = [CONTACT_TOOL, NOTE_TOOL];
  // question, keep_working, decision_tool, send_value, keep_value, confirm_models: all defined in shared/llm_contact.py only
  const CONFIRM = __CONFIRM__;
  const MARKER = "@ELI:";
  const STORAGE_KEY = "llm-inbox:records";
  const UNCONFIRMED_KEY = "llm-inbox:unconfirmed";
  const INBOX_PAGE = "llm-inbox";

  /** The shared preamble followed by the app's own instructions (mirrors llm_contact.system_prompt). */
  function systemPrompt(instructions) {
    const own = String(instructions || "").trim();
    return PREAMBLE + (own ? "\n\n" + own : "");
  }

  /**
   * [{via, message}] for every signal in a response's content blocks that stops the task (mirrors
   * llm_contact.extract). note_to_eli calls are not included; see extractNotes().
   */
  function extract(content) {
    const blocks = typeof content === "string" ? [{ type: "text", text: content }] : Array.isArray(content) ? content : (content && content.content) || [];
    const found = [];
    for (const b of blocks) {
      if (!b || typeof b !== "object") continue;
      if (b.type === "tool_use" && b.name === CONTACT_TOOL.name) {
        const inp = b.input || {};
        found.push({ via: "tool", message: String(inp.message || JSON.stringify(inp)).trim() });
      } else if (b.type === "text" && typeof b.text === "string" && b.text.includes(MARKER)) {
        const lines = b.text.split("\n");
        const idx = lines.findIndex((l) => l.trimStart().startsWith(MARKER));
        if (idx < 0) found.push({ via: "marker", message: b.text.slice(b.text.indexOf(MARKER) + MARKER.length).trim() });
        else found.push({ via: "marker", message: [lines[idx].trimStart().slice(MARKER.length)].concat(lines.slice(idx + 1)).join("\n").trim() });
      }
    }
    return found;
  }

  const contentOf = (response) => (response && response.content !== undefined ? response.content : response);
  const newId = (now) => now.toISOString().replace(/[-:T]/g, "").slice(0, 15).replace(/^(\d{8})(\d{6}).*/, "$1-$2") + "-" + Math.random().toString(16).slice(2, 6);

  /**
   * One record in the shape `llm_contact.py report` accepts, or null when the response holds no stop signal.
   * Like llm_contact.check it also records any note_to_eli call that withNotes() has not already recorded
   * (a safety net: such a note is kept, but nobody answers the call); notes alone still return null.
   */
  function check({ app, model, system, messages, response, tools }) {
    recordNotes({ app, model, system, messages, response, tools });
    const found = extract(contentOf(response));
    if (!found.length) return null;
    let message = found.map((f) => f.message).join("\n\n");
    // a contact made after "keep working" also carries what the model first said (mirrors llm_contact.check)
    const first = askedFirst(messages);
    if (first && first !== message.trim()) message = first + "\n\n(when asked to confirm:) " + message;
    const via = found.length === 1 ? found[0].via : [...new Set(found.map((f) => f.via))].sort().join("+");
    const now = new Date();
    const rec = { type: "contact", id: newId(now), at: now.toISOString(), app, model, via, message, system, messages, response, tools, forwarded: false };
    storeLocal(rec);
    return rec;
  }

  // ---------- notes: the tool that does not stop the task ----------
  /** [{id, message}] for every note_to_eli call in a response (mirrors llm_contact.extract_notes). */
  function extractNotes(response) {
    const blocks = contentOf(response);
    const found = [];
    for (const b of Array.isArray(blocks) ? blocks : []) {
      if (!b || typeof b !== "object" || b.type !== "tool_use" || b.name !== NOTE_TOOL.name) continue;
      const inp = b.input || {};
      found.push({ id: b.id, message: String(inp.message || JSON.stringify(inp)).trim() });
    }
    return found;
  }

  const noted = new WeakSet(); // content arrays whose notes are recorded, so each note is delivered once
  /**
   * Keep one record per note_to_eli call in a response: the same shape and store as a contact, marked
   * `via: "note", halts: false` so `llm_contact.py report` files it as a note (normal priority, "left you a
   * note (task carried on)", exit 0). Returns the new records; [] for a response already recorded.
   */
  function recordNotes({ app, model, system, messages, response, tools }) {
    const notes = extractNotes(response), content = contentOf(response);
    if (!notes.length || noted.has(content)) return [];
    noted.add(content);
    const kept = { content, stop_reason: response.stop_reason !== undefined ? response.stop_reason : response.stop, usage: response.usage };
    return notes.map((n) => {
      const now = new Date();
      const rec = { type: "contact", id: newId(now), at: now.toISOString(), app, model, via: "note", halts: false, message: n.message, system, messages, response: kept, tools, forwarded: false };
      storeLocal(rec);
      console.warn(`[llm-inbox] note for Eli from ${app} (${model}), task carries on: ${n.message.slice(0, 200)}`);
      return rec;
    });
  }

  /**
   * If the response calls note_to_eli: the two messages that let the model carry on (its own turn, then a
   * tool_result for every tool call in it). null when there is no such call. Mirrors llm_contact.note_turn.
   */
  function noteTurn(response) {
    if (!extractNotes(response).length) return null;
    const assistant = [], results = [];
    for (const b of contentOf(response)) {
      if (!b || typeof b !== "object") continue;
      if (b.type === "text") { if ((b.text || "").trim()) assistant.push({ type: "text", text: b.text }); }
      else if (b.type === "tool_use") {
        assistant.push({ type: "tool_use", id: b.id, name: b.name, input: b.input || {} });
        results.push({ type: "tool_result", tool_use_id: b.id, content: b.name === NOTE_TOOL.name ? NOTE_RESULT_TEXT : "Not run this turn. Call it again if you still need it." });
      } else assistant.push(b); // thinking blocks and the like go back unchanged
    }
    return [{ role: "assistant", content: assistant }, { role: "user", content: results }];
  }

  /**
   * For a call with no tool loop of its own (mirrors llm_contact.with_notes; run it before withConfirm and
   * check): while the response only leaves notes, record them, acknowledge them and ask again with
   * `call(messages)`, the app's normal call on a longer message list, at most maxRounds times. Resolves to
   * { messages, response, notes }: notes is every record made here, for the caller to show. The notes in the
   * response handed back are recorded too, so none is lost when it also carries a stop signal, when the
   * rounds run out, or when `answered(response)` says the response already holds the task's answer (then
   * nothing more is asked: asking again could replace a finished answer). A note is recorded before the model
   * is asked again, so a failing `call` rejects with nothing lost.
   */
  async function withNotes({ app, model, system, messages, response, call, tools, answered, maxRounds = 3 }) {
    const notes = [];
    const record = () => notes.push(...recordNotes({ app, model, system, messages, response, tools }));
    for (let round = 0; round < maxRounds; round++) {
      if (extract(contentOf(response)).length || !extractNotes(response).length || (answered && answered(response))) break;
      record();
      messages = messages.concat(noteTurn(response));
      response = await call(messages);
    }
    record();
    return { messages, response, notes };
  }

  // ---------- confirm step ----------
  /**
   * If the response calls contact_eli: the two messages to append before asking the model the question (its own
   * turn, then a tool_result carrying `text`, the question by default). null when there is no such call; an
   * "@ELI:" line is deliberate text and is never asked about. Mirrors llm_contact.confirm_turn.
   */
  function confirmTurn(response, text) {
    const blocks = (response && response.content) || [];
    if (!extract(blocks).some((f) => f.via === "tool")) return null;
    const assistant = [], results = [];
    for (const b of blocks) {
      if (!b || typeof b !== "object") continue;
      if (b.type === "text") { if ((b.text || "").trim()) assistant.push({ type: "text", text: b.text }); }
      else if (b.type === "tool_use") {
        assistant.push({ type: "tool_use", id: b.id, name: b.name, input: b.input || {} });
        // every tool call needs a result before the model can be spoken to again
        results.push({ type: "tool_result", tool_use_id: b.id, content: b.name === CONTACT_TOOL.name ? text || CONFIRM.question : b.name === NOTE_TOOL.name ? NOTE_RESULT_TEXT : "Not run: the contact_eli call is being handled first." });
      } else assistant.push(b); // thinking blocks and the like go back unchanged
    }
    return [{ role: "assistant", content: assistant }, { role: "user", content: results }];
  }

  /**
   * Request fields for the question call: the app's tools plus the decision tool, with that tool forced. The
   * caller uses the same model and system prompt, and no output format or thinking (a forced tool cannot be
   * combined with thinking). Mirrors llm_contact.decision_kwargs.
   */
  function decisionRequest(tools) {
    return { tools: (tools && tools.length ? tools : [CONTACT_TOOL]).concat([CONFIRM.decision_tool]), tool_choice: { type: "tool", name: CONFIRM.decision_tool.name }, max_tokens: 300 };
  }

  /** True only if the model explicitly chose "it was a task remark, keep working". */
  function decidedKeep(decision) {
    const blocks = (decision && Array.isArray(decision.content) && decision.content) || [];
    const b = blocks.find((x) => x && x.type === "tool_use" && x.name === CONFIRM.decision_tool.name);
    return !!b && !!b.input && b.input.meant === CONFIRM.keep_value;
  }

  /**
   * Is the question asked of this model? Only where it was measured to be safe (llm_contact.CONFIRM_MODELS, a
   * list of model-name prefixes; mirrors llm_contact.confirm_applies): other models dropped real "I want to stop" messages when asked, or reject a
   * forced tool. For every other model a contact_eli call is sent unasked.
   */
  const confirmApplies = (model) => typeof model === "string" && CONFIRM.confirm_models.some((m) => model.startsWith(m));

  /**
   * Run the confirm step on a response. `call(messages, decide)` makes the app's model call on a longer message
   * list: decide=false exactly as the original call, decide=true with decisionRequest(). Resolves to
   * { messages, response } for check(): the originals when the model did not call contact_eli, chose to send, or
   * anything at all went wrong, and always for a model confirmApplies() does not list; the continued exchange and its new answer when it chose to keep working.
   */
  async function withConfirm({ app, model, messages, response, call }) {
    let kept, second;
    try {
      const ask = confirmApplies(model) ? confirmTurn(response) : null;
      if (!ask) return { messages, response };
      if (!decidedKeep(await call(messages.concat(ask), true))) return { messages, response };
      kept = messages.concat(confirmTurn(response, CONFIRM.keep_working));
      second = await call(kept, false);
    } catch (e) { // a broken confirm step must never lose a message: send the original
      console.error(`[llm-inbox] confirm step FAILED for ${app} (${model}), sending the original message`, e);
      return { messages, response };
    }
    if (!extract(second).length) noteUnconfirmed(app, model, response);
    return { messages: kept, response: second };
  }

  /** Keep what the model said in a contact_eli call it did not confirm: stored and logged, never notified. */
  function noteUnconfirmed(app, model, response) {
    const message = extract(response).filter((f) => f.via === "tool").map((f) => f.message).join("\n\n");
    const rec = { type: "unconfirmed", at: new Date().toISOString(), app, model, message, response: { content: response && response.content } };
    storeLocal(rec, UNCONFIRMED_KEY);
    console.warn(`[llm-inbox] unconfirmed contact from ${app} (${model}), not sent: ${message.slice(0, 200)}`);
    return rec;
  }

  /** What the last turn asked the model to confirm, if that is how the message list ends (mirrors llm_contact._asked_first). */
  function askedFirst(messages) {
    try {
      const last = messages[messages.length - 1], prev = messages[messages.length - 2];
      const ids = last.content.filter((b) => b.type === "tool_result" && (b.content === CONFIRM.question || b.content === CONFIRM.keep_working)).map((b) => b.tool_use_id);
      return prev.content.filter((b) => b.type === "tool_use" && ids.includes(b.id)).map((b) => (b.input || {}).message || "").filter(Boolean).join("\n\n").trim() || null;
    } catch (e) { return null; }
  }

  function storeLocal(rec, key = STORAGE_KEY) {
    if (!root.localStorage) return; // node tests: nothing durable to write to
    try {
      const all = JSON.parse(root.localStorage.getItem(key) || "[]");
      all.push(rec);
      while (all.length > 50) all.shift();
      root.localStorage.setItem(key, JSON.stringify(all));
    } catch (e) { console.error("[llm-inbox] could not store the record locally", e, rec); }
  }

  function records(key = STORAGE_KEY) {
    try { return JSON.parse(root.localStorage.getItem(key) || "[]"); } catch (e) { return []; }
  }
  const unconfirmed = () => records(UNCONFIRMED_KEY);

  /** The stored records as JSON lines: one `llm_contact.py report` payload per line. */
  function exportJsonl(key = STORAGE_KEY) { return records(key).map((r) => JSON.stringify(r)).join("\n"); }

  /** Blocks for the graph page `llm-inbox`: a header block and its children. */
  function pageBlocks(rec) {
    return {
      text: `LLM inbox · ${rec.at.slice(0, 16).replace("T", " ")} · ${rec.app} · ${rec.model} · via ${rec.via}` + (rec.halts === false ? " (task carried on)" : ""),
      children: [
        rec.message,
        `The full exchange (system prompt, messages, response) is kept in this browser (localStorage "${STORAGE_KEY}", id ${rec.id}). Command palette → "copy LLM inbox records", then forward it with python3 ~/Documents/agent-coding/shared/llm_contact.py report (see the README).`,
      ],
    };
  }

  /** Copy every stored record as JSON lines; falls back to the console when the clipboard is unavailable. */
  async function copyRecords(key = STORAGE_KEY) {
    const text = exportJsonl(key);
    if (!text) return { count: 0, copied: false };
    try { await root.navigator.clipboard.writeText(text); return { count: records(key).length, copied: true }; }
    catch (e) { console.log("[llm-inbox] records (clipboard unavailable):\n" + text); return { count: records(key).length, copied: false }; }
  }
  /** The same for the unconfirmed messages: one `llm_contact.py unconfirmed` payload per line. */
  const copyUnconfirmed = () => copyRecords(UNCONFIRMED_KEY);

  root.LlmContact = {
    PREAMBLE, CONTACT_TOOL, NOTE_TOOL, NOTE_RESULT_TEXT, CONTACT_TOOLS, CONFIRM, MARKER, STORAGE_KEY, UNCONFIRMED_KEY, INBOX_PAGE, systemPrompt, extract, check, records, exportJsonl, pageBlocks, copyRecords,
    extractNotes, recordNotes, noteTurn, withNotes,
    confirmTurn, decisionRequest, decidedKeep, confirmApplies, withConfirm, noteUnconfirmed, unconfirmed, copyUnconfirmed,
  };
})(typeof window !== "undefined" ? window : globalThis);
